// Détecte les events qui méritent une notification, dédoublonne sur 24h, limite anti-spam.
const now = Date.now();
const MAX_NEW_PER_RUN = 8; // anti-flood
const DEDUP_WINDOW_H = 24;

const bcl = $('Lire business_control').all().map(i=>i.json);
const review = $('Lire review_queue').all().map(i=>i.json);
const projects = $('Lire project_queue').all().map(i=>i.json);
const invoices = $('Lire invoices').all().map(i=>i.json);
const inbox = $('Lire notifications_inbox (dedup)').all().map(i=>i.json);

const recentKeys = new Set(
  inbox.filter(n => {
    const t = Date.parse(n.ts || ''); return Number.isFinite(t) && (now - t) < DEDUP_WINDOW_H*3600*1000;
  }).map(n => `${n.kind}|${n.item_id}`)
);

function lower(v){return String(v||'').toLowerCase();}
function daysSince(iso){if(!iso) return null; const t=Date.parse(iso); return Number.isFinite(t)?Math.floor((now-t)/86400000):null;}
function daysUntil(iso){if(!iso) return null; const t=Date.parse(iso); return Number.isFinite(t)?Math.floor((t-now)/86400000):null;}

const events = [];

// 1) Critical pending dans business_control
for (const b of bcl) {
  if (lower(b.decision_status) !== 'pending') continue;
  if (lower(b.priority_level) !== 'critical') continue;
  const key = `bcl_critical|${b.id}`;
  if (recentKeys.has(key)) continue;
  events.push({
    kind: 'bcl_critical',
    severity: 'critical',
    title: `Critical à valider : ${b.title || b.item_id}`,
    body: (b.recommendation || '').slice(0, 140),
    deeplink: `#decisions/${b.id}`,
    source_workflow: b.source_workflow || 'WF7',
    item_id: b.id
  });
}

// 2) Nouvelle réponse intéressante (interested ou needs_quote, dernière 6h)
for (const r of review) {
  const cat = lower(r.reply_category);
  if (!['interested','needs_quote'].includes(cat)) continue;
  const t = Date.parse(r.reply_received_at || ''); if (!Number.isFinite(t)) continue;
  if ((now - t) > 6*3600*1000) continue;
  const key = `reply_hot|${r.id}|${cat}`;
  if (recentKeys.has(key)) continue;
  events.push({
    kind: 'reply_hot',
    severity: 'high',
    title: `Réponse ${cat} : ${r.company_name || r.id}`,
    body: String(r.reply_text || '').slice(0, 140),
    deeplink: `#prospects/${r.id}`,
    source_workflow: 'WF4',
    item_id: r.id
  });
}

// 3) Projet bloqué ou deadline imminente
for (const p of projects) {
  const status = lower(p.status);
  const dueIn = daysUntil(p.deadline);
  let kind = null, severity = 'high';
  if (status === 'blocked') { kind = 'project_blocked'; }
  else if (dueIn !== null && dueIn <= 3 && ['new','in_progress'].includes(status)) { kind = 'project_deadline'; severity = 'critical'; }
  if (!kind) continue;
  const key = `${kind}|${p.id}`;
  if (recentKeys.has(key)) continue;
  events.push({
    kind,
    severity,
    title: kind === 'project_blocked' ? `Projet bloqué : ${p.client_name || p.id}` : `Deadline ${dueIn}j : ${p.client_name || p.id}`,
    body: (p.client_brief_summary || '').slice(0, 140),
    deeplink: `#projects/${p.id}`,
    source_workflow: 'WF11',
    item_id: p.id
  });
}

// 4) Facture en retard >=14 jours
for (const inv of invoices) {
  const status = lower(inv.status);
  if (!['sent','overdue','partial'].includes(status)) continue;
  const od = daysSince(inv.due_date);
  if (od === null || od < 14) continue;
  const key = `invoice_overdue|${inv.id || inv.invoice_ref}`;
  if (recentKeys.has(key)) continue;
  events.push({
    kind: 'invoice_overdue',
    severity: od >= 30 ? 'critical' : 'high',
    title: `Facture ${inv.invoice_ref || inv.id} en retard ${od}j`,
    body: `Client ${inv.client_name || ''}, ${inv.amount_eur ? inv.amount_eur+' €' : ''}`,
    deeplink: `#decisions`,
    source_workflow: 'WF14',
    item_id: inv.id || inv.invoice_ref
  });
}

// 5) Synthèse du matin (lundi, 1 fois/jour)
const d = new Date();
if (d.getHours() >= 7 && d.getHours() <= 9 && d.getDay() === 1) {
  const todayKey = `morning_digest|${d.toISOString().slice(0,10)}`;
  if (!recentKeys.has(todayKey)) {
    const lastDigest = bcl.filter(b => b.source_workflow === 'WF8').sort((a,b)=>String(b.ts||'').localeCompare(String(a.ts||'')))[0];
    events.push({
      kind: 'morning_digest',
      severity: 'info',
      title: 'Synthèse du matin disponible',
      body: lastDigest ? (lastDigest.recommendation || '').slice(0,140) : 'Ouvre Symbalyx pour le digest hebdo.',
      deeplink: '#today',
      source_workflow: 'WF9',
      item_id: todayKey
    });
  }
}

// Anti-flood : limite par run
const limited = events.slice(0, MAX_NEW_PER_RUN);
const nowIso = new Date().toISOString();
const expires = new Date(now + 7*86400*1000).toISOString();
return limited.map((e, idx) => ({ json: {
  id: 'notif_' + Date.now() + '_' + String(idx).padStart(2,'0'),
  ts: nowIso,
  kind: e.kind,
  severity: e.severity,
  title: e.title,
  body: e.body,
  deeplink: e.deeplink,
  source_workflow: e.source_workflow,
  item_id: e.item_id,
  read: 'false',
  delivered_channels: 'inapp',
  expires_at: expires
}}));
